import random, time
def retry_with_backoff(fn, attempts=3, base=0.05, cap=0.5):
    for i in range(attempts):
        try:
            return fn()
        except Exception:
            if i == attempts - 1:
                raise
            time.sleep(random.uniform(0, min(cap, base * 2**i)))
